function setup() {
	createCanvas(500, 800, true ? SVG : P2D); // createCanvas(windowWidth, windowHeight, SVG);
	// describe("different heighted rows of vertical lines with a random x position and further vertical lines with growing distance from each horizontal neigboars")
	stroke(16);
	loop();
}

function draw() {
	background(222);
	const m = ~~(max(width, height) * 0.05); // margin
	let y = m;
	while (y < height - m - m) {
		let h = ~~random(m, height/7);
		h = min(h, height-y-m)
		// if (h < m) break;
		let x = randomGaussian(width/2, 65);
		line(x, y, x, y+h)
		let d = 0.75;
		const df = random(1.11, 1.25)
		let lx = x;
		for (let i = 0; i < 49; i++) {
			const isInLeft = x-d > m;
			const isInRight = x+d < width-m;
			if (true || x+d>=lx+1) {
				lx = x+d;
				if (isInLeft) line(x-d, y, x-d, y+h)
				if (isInRight) line(x+d, y, x+d, y+h)
			}
			if (!(isInLeft || isInRight)) break;
			d *= df;
		}
		y += h * random(0.7, 1.1); // slightly overlapping
	}
	// noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton === LEFT) redraw();
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("mySketch.svg"); // Save the canvas as SVG
	}
}
